type Token string

const (
    TokenLiveSite     Token = "{{live_site}}"
    TokenConfirmLink  Token = "{{confirm_link}}"
    TokenZipLink      Token = "{{zip_link}}"
    TokenInstructions Token = "{{instructions_link}}"  // NEW - bugs_open/475.
                                                       // Config key stays instructions_url: the
                                                       // estate pairs a *_url KEY with a *_link
                                                       // PLACEHOLDER (domain_rent, domain_buy,
                                                       // stripe_portal all do). Not a slip.
    TokenDomainRent   Token = "{{domain_rent_link}}"
    TokenDomainBuy    Token = "{{domain_buy_link}}"
    TokenStripePortal Token = "{{stripe_portal_link}}"
    TokenDays         Token = "{{days}}"               // NOT a link. AdvertisedWindowDays.
)

// Vocabulary is THE source. fillTemplate and every sender's pre-claim guard are
// derived from it, so they cannot disagree.
var Vocabulary = []Token{ /* all of the above, in the order a letter reads */ }

// Availability is what ONE sender can say about ONE token on THIS dispatch.
type Availability struct {
    Value       string // resolved; "" means this dispatch has none
    Source      string // where it should have come from, for the refusal text
    NeverReason string // non-empty: this sender can NEVER produce it, and why
}

type Fill map[Token]Availability

// Check refuses BEFORE anything irreversible, in this order:
//  1. COVERAGE - every Vocabulary token must be declared. Unconditional: it does
//     NOT depend on the template naming the token, so growing the Vocabulary makes
//     an unteached sender refuse loudly and pre-stamp rather than latently.
//  2. AVAILABILITY - a named token with an empty Value, or any NeverReason, refuses
//     and says which and why.
func (f Fill) Check(template string) error

// Apply substitutes from the SAME map Check read. That identity is the whole point.
func (f Fill) Apply(template string) string

f := delivery.Fill{
    delivery.TokenLiveSite:     {Value: prepared.Links.LiveSite},
    delivery.TokenConfirmLink:  {Value: prepared.Links.ConfirmTransfer},
    delivery.TokenDays:         {Value: fmt.Sprintf("%d", prepared.AdvertisedWindowDays)},
    delivery.TokenZipLink:      {Value: zipPresign, Source: "zip_presigned_url"},
    delivery.TokenInstructions: {Value: stringOr(config, "instructions_url"),
                                 Source: "instructions_url config"},
    delivery.TokenDomainRent:   {Value: stringOr(config, "domain_rent_url"),
                                 Source: "domain_rent_url config"},
    ... // every Vocabulary token; omitting one is now itself the refusal
}
if err := f.Check(bodyTemplate); err != nil {   // BEFORE delivery.Claim
    return nil, fmt.Errorf("delivery email refused before claim: %w", err)
}
// ... delivery.Claim stamps ...
body := f.WithLinks(prepared).Apply(bodyTemplate)

f := delivery.Fill{
    delivery.TokenZipLink: {NeverReason: "a scheduled follow-up has no step that can mint a presign"},
    delivery.TokenInstructions: {Value: stringOr(config, "instructions_url"),
                                 Source: "instructions_url config"},
    ... // and the rest; coverage is now enforced, not remembered
}
if err := f.Check(bodyTemplate); err != nil { ... }
// the strings.ReplaceAll(bodyTemplate, "{{instructions_url}}", ...) wrapper is DELETED

func AssertCoversVocabulary(t *testing.T, f Fill) {
    t.Helper()
    for _, tok := range Vocabulary {
        if _, ok := f[tok]; !ok { t.Fatalf("sender does not declare %s", tok) }
    }
    for tok := range f {
        if !slices.Contains(Vocabulary, tok) { t.Fatalf("sender invents %s", tok) }
    }
}
// and, in each sender's test package:
func TestDeliverySenderCoversVocabulary(t *testing.T) { delivery.AssertCoversVocabulary(t, ...) }
func TestFollowupSenderCoversVocabulary(t *testing.T) { delivery.AssertCoversVocabulary(t, ...) }

