type Links struct {
    ...
    DomainRent   string // the GBP10/mo domain-rental link - EMPTY unless domain_rent_url is configured
    DomainBuy    string // the domain buy-out link - EMPTY unless domain_buy_url is configured
    StripePortal string // the Stripe customer-portal link - EMPTY unless stripe_portal_url is configured
    Instructions string // the hosting-instructions page. DURABLE and PUBLIC by design:
                        // no token, no lifetime, because the scheduled follow-up sender
                        // has no step that can mint one and must carry the same link.
}
